// @FIGURE_CODE_BEGIN
var GDraw = SVG().addTo('#container').size('100%', '100%');
var VW = 1640, VH = 565;
GDraw.viewbox(0, 0, VW, VH);

var C = {
  slate: '#4a7289', slateDk: '#27536a', brick: '#8e3b25', orange: '#bf5f38',
  teal: '#2f8f7c', cell: '#cfcfcf', ink: '#333333'
};
var ORANGE = ['#f7dccb', '#eeb694', '#e08a5e', '#c05730', '#93321d', '#682312'];
var TEAL = ['#d9ede8', '#b0ded2', '#7fcab8', '#3fae95', '#1f836f', '#10584a'];
