/* ── state ────────────────────────────────────────────────────────────── */
var SEL = null;
var PANEL = 'All panels';

function applyPanels() {
  var map = {
    'All panels': { g: 1, a: 1, x: 1, e: 1 },
    'Graph only': { g: 1, a: 0.14, x: 0.14, e: 0.14 },
    'Adjacency A': { g: 0.3, a: 1, x: 0.14, e: 0.14 },
    'Node data X': { g: 0.3, a: 0.14, x: 1, e: 0.14 },
    'Edge data E': { g: 0.3, a: 0.14, x: 0.14, e: 1 }
  };
  var m = map[PANEL] || map['All panels'];
  gGraph.animate(220).attr('opacity', m.g);
  gA.animate(220).attr('opacity', m.a);
  gX.animate(220).attr('opacity', m.x);
  gE.animate(220).attr('opacity', m.e);
