function drawHighlight() {
  gHi.clear();
  if (!SEL) return;
  if (SEL.type === 'node') {
    var n = SEL.id, nd = NODES[n];
    var ring = gHi.circle(74).center(nd.x, nd.y).fill('none')
      .stroke({ color: C.orange, width: 6, opacity: 0.6 });
    ring.animate(1100).attr({ 'stroke-opacity': 0.18 }).loop(true, true);
    gHi.rect(SQ + 12, 4 * SP + SQ + 12).radius(7).move(nd.sx - 6, nd.sy - 6)
      .fill('none').stroke({ color: C.orange, width: 2.5, opacity: 0.85 });
    // row + column band in A
    gHi.rect(AW + 12, CA + 10).radius(7).move(AGX - 6, AGY + (n - 1) * PA - 5)
      .fill({ color: C.slate, opacity: 0.2 }).stroke({ color: C.slateDk, width: 2, opacity: 0.7 });
    gHi.rect(CA + 10, AH + 12).radius(7).move(AGX + (n - 1) * PA - 5, AGY - 6)
      .fill({ color: C.slate, opacity: 0.2 }).stroke({ color: C.slateDk, width: 2, opacity: 0.7 });
    // column of X
    gHi.rect(CX + 12, XH + 12).radius(7).move(XGX + (n - 1) * PX - 6, XGY - 6)
      .fill('none').stroke({ color: C.brick, width: 3.5 });
  } else {
    var kk = SEL.k, e = EDGES[kk], a = NODES[e[0]], b = NODES[e[1]];
    var glow = gHi.line(a.x, a.y, b.x, b.y)
      .stroke({ color: C.teal, width: 11, opacity: 0.4, linecap: 'round' });
    glow.animate(1100).attr({ 'stroke-opacity': 0.12 }).loop(true, true);
    gHi.line(a.x, a.y, b.x, b.y).stroke({ color: C.slateDk, width: 4, linecap: 'round' });
    [a, b].forEach(function (p) {
      gHi.circle(66).center(p.x, p.y).fill('none').stroke({ color: C.orange, width: 3, opacity: 0.5 });
    });
    gHi.rect(SQ + 12, 3 * SP + SQ + 12).radius(7).move(ESTACK[kk][0] - 6, ESTACK[kk][1] - 6)
      .fill('none').stroke({ color: C.teal, width: 2.5, opacity: 0.9 });
    // mirrored cells in A
    [[e[0], e[1]], [e[1], e[0]]].forEach(function (p) {
      gHi.rect(CA + 10, CA + 10).radius(7).move(AGX + (p[1] - 1) * PA - 5, AGY + (p[0] - 1) * PA - 5)
        .fill('none').stroke({ color: C.slateDk, width: 3.5 });
    });
    // column of E
    gHi.rect(CE + 12, EH + 12).radius(7).move(EGX + kk * PE - 6, EGY - 6)
