        .fill('none').stroke({ color: C.slateDk, width: 3.5 });
    });
    // column of E
    gHi.rect(CE + 12, EH + 12).radius(7).move(EGX + kk * PE - 6, EGY - 6)
      .fill('none').stroke({ color: C.teal, width: 3.5 });
  }
}

function updateInfo() {
  var el = document.getElementById('selInfo');
  if (!el) return;
  if (!SEL) { el.textContent = 'Nothing selected.'; return; }
  if (SEL.type === 'node') {
    var nb = neighbours(SEL.id);
    el.textContent = 'Node ' + SEL.id + ': degree ' + nb.length + ' (neighbours ' + nb.join(', ') +
      '). It is row ' + SEL.id + ' AND column ' + SEL.id + ' of A, and column ' + SEL.id + ' of X (5 features).';
  } else {
    var e = EDGES[SEL.k];
    el.textContent = 'Edge ' + e[0] + '–' + e[1] + ': filled at A[' + e[0] + ',' + e[1] + '] and A[' +
      e[1] + ',' + e[0] + '] (symmetric), and stored as column ' + (SEL.k + 1) + ' of E (4 features).';
  }
}

function syncGuided() {
  var g = document.getElementById('guidedHighlightInput');
  if (!g) return;
  var v = 'none';
  if (SEL && SEL.type === 'node' && (SEL.id === 3 || SEL.id === 5)) v = 'node ' + SEL.id;
  else if (SEL && SEL.type === 'edge') {
    var e = EDGES[SEL.k];
    if (e[0] === 3 && e[1] === 4) v = 'edge 3–4';
    else if (e[0] === 5 && e[1] === 6) v = 'edge 5–6';
    else v = 'custom';
  } else if (SEL) v = 'custom';
  g.value = v;
}

function render() { applyPanels(); drawHighlight(); updateInfo(); }

function selectNode(n, fromClick) {
  SEL = { type: 'node', id: n };
  syncGuided(); render();
  if (fromClick) {
    var nb = neighbours(n);
    showPopup('Node ' + n,
      'Node ' + n + ' appears three times in the encoding: as row ' + n + ' of A, as column ' + n +
      ' of A (both list its neighbours ' + nb.join(', ') + '), and as column ' + n +
      ' of the node-feature matrix X, which holds its D = 5 attribute values. ' +
      'The number of filled cells in its row of A, ' + nb.length + ', is its degree.');
  }
}
function selectEdge(k, fromClick) {
  SEL = { type: 'edge', k: k };
  syncGuided(); render();
  if (fromClick) {
    var e = EDGES[k];
    showPopup('Edge ' + e[0] + '–' + e[1],
      'Because the graph is undirected, this single edge is stored twice in A: at (' + e[0] + ',' + e[1] +
      ') and at (' + e[1] + ',' + e[0] + '). Its D_E = 4 attributes live in column ' + (k + 1) +
      ' of E, whose header names the endpoint pair. A alone tells you the edge exists; only E tells you what it carries.');
  }
}

function toggle_panelView(v) { PANEL = v; render(); }
function state_guidedHighlight(v) {
  if (v === 'custom') return;
  if (v === 'none') { SEL = null; }
  else if (v === 'node 3') { SEL = { type: 'node', id: 3 }; }
  else if (v === 'node 5') { SEL = { type: 'node', id: 5 }; }
  else if (v === 'edge 3–4') { SEL = { type: 'edge', k: edgeIndex(3, 4) }; }
  else if (v === 'edge 5–6') { SEL = { type: 'edge', k: edgeIndex(5, 6) }; }
  render();
}
function trigger_clear() {
  SEL = null;
  document.getElementById('guidedHighlightInput').value = 'none';
  hidePopup(); render();
}

/* ── demo steps ───────────────────────────────────────────────────────── */
var STEPS = [
  {
    title: 'Overview', narration: 'A graph with attributes is not one array but three: A (who connects to whom), X (one column of features per node) and E (one column per edge). Click any node, edge or matrix cell to see the same object in both the picture and the matrices.',
    state: { panelView: 'All panels', guidedHighlight: 'none' }
  },
  {
    title: 'The graph itself', narration: 'Six nodes joined by seven undirected edges. Each node carries a D-dimensional feature vector (orange stack) and each edge carries a D_E-dimensional feature vector (teal stack).',
    state: { panelView: 'Graph only', guidedHighlight: 'none' }
  },
  {
    title: 'Structure becomes A', narration: 'The adjacency matrix records only who is connected to whom: a filled cell at (i,j) and at (j,i) for every edge, empty diagonal because no node links to itself.',
    state: { panelView: 'Adjacency A', guidedHighlight: 'none' }
  },
  {
    title: 'A node is a row, a column, and a column', narration: 'Node 3 lights up: its row and column in A show its four neighbours (1, 2, 4, 6), and its single column in X holds its five features.',
    state: { panelView: 'All panels', guidedHighlight: 'node 3' }
  },
  {
    title: 'Degree is visible in A', narration: 'Node 5 has only two neighbours, so its row and column in A contain just two filled cells — the row sum of A is the node\u2019s degree.',
    state: { panelView: 'All panels', guidedHighlight: 'node 5' }
  },
  {
    title: 'An edge is two cells and one column', narration: 'Selecting edge 3–4 highlights the symmetric pair of cells in A and the matching column of E, whose header names the endpoint pair.',
    state: { panelView: 'All panels', guidedHighlight: 'edge 3–4' }
  },
  {
    title: 'Edge ordering matters', narration: 'Edge 5–6 is the last column of E; the column order of E is an arbitrary but fixed listing of the edges, and A alone cannot tell you which column of E belongs to which edge.',
    state: { panelView: 'Edge data E', guidedHighlight: 'edge 5–6' }
  },
  {
    title: 'All three together', narration: 'A, X and E together reconstruct the whole annotated graph — this triple is exactly what a graph neural network consumes.',
    state: { panelView: 'All panels', guidedHighlight: 'none' }
  }
];
var STEP = 0;

function setStep(i) {
  STEP = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[STEP];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (STEP === 0 ? 'intro' : 'step ' + STEP + ' / 7');
  var pv = document.getElementById('panelViewInput');
  pv.value = s.state.panelView; toggle_panelView(s.state.panelView);
  var gh = document.getElementById('guidedHighlightInput');
  gh.value = s.state.guidedHighlight; state_guidedHighlight(s.state.guidedHighlight);
}
function nextStep() { setStep(STEP + 1); }
function prevStep() { setStep(STEP - 1); }

setStep(0);
render();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A graph with attributes is fully encoded for deep learning by three matrices: the adjacency matrix A (who connects to whom), the node feature matrix X (one column per node), and the edge feature matrix E (one column per edge).
KEY INSIGHT (what students should walk away understanding): A graph is not one array but three: A stores connectivity (N×N), X stores per-node features (D×N), and E stores per-edge features (D_E×E) — clicking any node or edge shows the same object appearing simultaneously in the picture and in a specific row/column of those matrices.
DEMO STEPS: 7 guided steps — implement the step player in #ui

FULL BLUEPRINT:
