// @FIGURE_CODE_BEGIN
var GDraw = SVG().addTo('#container').size('100%', '100%');
var VW = 1260, VH = 470;
GDraw.viewbox(0, 0, VW, VH);

var C = {
  slate: '#4a7289', slateDk: '#2c5468', brick: '#8e3b25',
  nodeDark: '#9a3d22', nodeLite: '#cb7a52',
  edgeDark: '#1f7d69', edgeLite: '#59b8a3',
  ink: '#2b2b2b'
};
var ORANGE = ['#f4d8c6', '#eab391', '#dd8a5d', '#bd5730', '#93321d', '#682312'];
var TEAL = ['#d8ece7', '#aedccf', '#7dc9b6', '#3dac93', '#1f836f', '#0f5648'];
var FF = 'Helvetica, Arial, sans-serif';

/* ── data ─────────────────────────────────────────────────────────────── */
var NODES = {
  1: { x: 230, y: 80, sx: 258, sy: 2 },
  2: { x: 48, y: 105, sx: 86, sy: 48 },
  3: { x: 140, y: 265, sx: 98, sy: 285 },
  4: { x: 400, y: 105, sx: 428, sy: 22 },
  5: { x: 505, y: 222, sx: 533, sy: 185 },
  6: { x: 305, y: 395, sx: 335, sy: 378 }
};
var EDGES = [[1, 3], [1, 4], [2, 3], [3, 4], [3, 6], [4, 5], [5, 6]];
var ESTACK = [[214, 128], [330, 12], [48, 168], [290, 182], [192, 330], [478, 112], [430, 318]];

var X_IDX = [
  [2, 1, 2, 2, 5, 4],
  [4, 4, 1, 4, 3, 2],
  [4, 4, 1, 4, 4, 3],
  [3, 4, 3, 2, 2, 4],
  [1, 4, 4, 2, 4, 4]
];
var E_IDX = [
  [5, 3, 1, 0, 1, 0, 0],
  [1, 1, 2, 4, 1, 0, 0],
  [0, 3, 0, 4, 5, 1, 0],
  [1, 4, 4, 4, 1, 2, 0]
];

/* ── geometry ─────────────────────────────────────────────────────────── */
var NR = 22, SQ = 13, SP = 16;
var CA = 30, PA = 34, AGX = 630, AGY = 214, AW = 5 * PA + CA, AH = AW;
var CX = 30, PX = 34, XGX = 1052, XGY = 48, XW = 5 * PX + CX, XH = 4 * PX + CX;
var CE = 30, PE = 34, EGX = 1016, EGY = 322, EW = 6 * PE + CE, EH = 3 * PE + CE;

var gGraph = GDraw.group(), gA = GDraw.group(), gX = GDraw.group(), gE = GDraw.group();
var gHi = GDraw.group();

/* ── helpers ──────────────────────────────────────────────────────────── */
function txt(parent, s, x, y, size, fill, anchor, italic, weight) {
  var t = parent.text(' ');
  t.node.textContent = s;
  t.attr({
    x: x, y: y, 'text-anchor': anchor || 'middle', 'dominant-baseline': 'central',
    'font-family': FF, 'font-size': size, fill: fill || C.ink
  });
  if (italic) t.attr('font-style', 'italic');
  if (weight) t.attr('font-weight', weight);
  return t;
}
/* segments: {s,size,fill,bold,italic,dy,gap} laid out on one baseline */
function drawSegLine(parent, segs, x, y, align) {
  var els = [], total = 0, i;
  for (i = 0; i < segs.length; i++) {
    var s = segs[i];
    var t = txt(parent, s.s, 0, y + (s.dy || 0), s.size, s.fill, 'start', s.italic, s.bold ? 'bold' : null);
    var w;
    try { w = t.bbox().width; } catch (e) { w = s.s.length * s.size * 0.55; }
    if (!isFinite(w) || w <= 0) w = s.s.length * s.size * 0.55;
    els.push({ t: t, w: w, gap: s.gap || 0 });
    total += w + (s.gap || 0);
  }
  var cx = (align === 'middle') ? x - total / 2 : (align === 'end' ? x - total : x);
  for (i = 0; i < els.length; i++) { els[i].t.attr('x', cx); cx += els[i].w + els[i].gap; }
}
function cellRect(parent, x, y, s, fill, stroke, sw) {
  return parent.rect(s, s).radius(Math.max(2, s * 0.14)).move(x, y)
    .fill(fill).stroke({ color: stroke, width: sw || 1.2 });
}
function hover(el, text) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(text, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  return el;
}
function edgeIndex(a, b) {
  for (var k = 0; k < EDGES.length; k++) {
    if ((EDGES[k][0] === a && EDGES[k][1] === b) || (EDGES[k][0] === b && EDGES[k][1] === a)) return k;
  }
  return -1;
}
function neighbours(n) {
  var out = [];
  for (var k = 0; k < EDGES.length; k++) {
    if (EDGES[k][0] === n) out.push(EDGES[k][1]);
    else if (EDGES[k][1] === n) out.push(EDGES[k][0]);
  }
  return out.sort(function (p, q) { return p - q; });
}

/* ── panel a) graph ───────────────────────────────────────────────────── */
txt(GDraw, 'a)', 8, 20, 28, C.ink, 'start');

var edgeEls = [];
for (var k0 = 0; k0 < EDGES.length; k0++) {
  (function (k) {
    var a = NODES[EDGES[k][0]], b = NODES[EDGES[k][1]];
    var ln = gGraph.line(a.x, a.y, b.x, b.y).stroke({ color: C.slate, width: 2.6, linecap: 'round' });
    var hit = gGraph.line(a.x, a.y, b.x, b.y)
      .stroke({ color: '#000', width: 16, opacity: 0 }).attr('pointer-events', 'stroke');
    hover(hit, 'Edge ' + EDGES[k][0] + '–' + EDGES[k][1] + ' — column ' + (k + 1) + ' of E');
    hit.on('click', function () { selectEdge(k, true); });
    var sg = gGraph.group();
    for (var r = 0; r < 4; r++) {
      var sq = cellRect(sg, ESTACK[k][0], ESTACK[k][1] + r * SP, SQ, TEAL[E_IDX[r][k]], '#ffffff', 0.9);
      hover(sq, 'Edge ' + EDGES[k][0] + '–' + EDGES[k][1] + ': feature ' + (r + 1) + ' of 4  (E[' + (r + 1) + ',' + (k + 1) + '])');
      sq.on('click', (function (kk) { return function () { selectEdge(kk, true); }; })(k));
    }
    edgeEls.push({ line: ln, hit: hit, stack: sg });
  })(k0);
}

for (var nid = 1; nid <= 6; nid++) {
  (function (n) {
    var nd = NODES[n];
    var sg = gGraph.group();
    for (var r = 0; r < 5; r++) {
      var sq = cellRect(sg, nd.sx, nd.sy + r * SP, SQ, ORANGE[X_IDX[r][n - 1]], '#ffffff', 0.9);
      hover(sq, 'Node ' + n + ': feature ' + (r + 1) + ' of 5  (X[' + (r + 1) + ',' + n + '])');
      sq.on('click', function () { selectNode(n, true); });
    }
    var cir = gGraph.circle(2 * NR).center(nd.x, nd.y).fill('#ffffff').stroke({ color: C.brick, width: 2.6 });
    var lbl = txt(gGraph, String(n), nd.x, nd.y + 1, 24, C.ink, 'middle');
    lbl.attr('pointer-events', 'none');
    hover(cir, 'Node ' + n + ' — row & column ' + n + ' of A, column ' + n + ' of X');
    cir.on('click', function () { selectNode(n, true); });
  })(nid);
}

/* ── panel b) adjacency ───────────────────────────────────────────────── */
txt(GDraw, 'b)', 575, 20, 28, C.ink, 'start');
drawSegLine(gA, [{ s: 'Adjacency', size: 28, fill: C.slate }], 730, 104, 'middle');
drawSegLine(gA, [{ s: 'matrix,', size: 28, fill: C.slate, gap: 9 },
{ s: 'A', size: 28, fill: C.slate, bold: true }], 730, 140, 'middle');
drawSegLine(gA, [{ s: 'N × N', size: 26, fill: C.slate, italic: true }], 730, 174, 'middle');

for (var i0 = 1; i0 <= 6; i0++) {
  txt(gA, String(i0), AGX + (i0 - 1) * PA + CA / 2, AGY - 18, 24, C.ink, 'middle');
  txt(gA, String(i0), AGX - 13, AGY + (i0 - 1) * PA + CA / 2, 24, C.ink, 'end');
}
for (var ri = 1; ri <= 6; ri++) {
  for (var ci = 1; ci <= 6; ci++) {
    (function (r, c) {
      var ek = edgeIndex(r, c);
      var on = ek >= 0;
      var rect = cellRect(gA, AGX + (c - 1) * PA, AGY + (r - 1) * PA, CA,
        on ? C.slate : '#ffffff', on ? C.slate : C.slate, 2.2);
      var tip = on
        ? 'A[' + r + ',' + c + '] = 1 — nodes ' + r + ' and ' + c + ' are connected'
        : (r === c ? 'A[' + r + ',' + r + '] = 0 — no self-loops (empty diagonal)'
          : 'A[' + r + ',' + c + '] = 0 — no edge between ' + r + ' and ' + c);
      hover(rect, tip);
      rect.on('click', function () { if (on) selectEdge(ek, true); else selectNode(r, true); });
    })(ri, ci);
  }
}

