/* ── state ────────────────────────────────────────────────────────────── */
var SEL = null;
var PANEL = 'All panels';

function applyPanels() {
  var map = {
    'All panels': { g: 1, a: 1, x: 1, e: 1 },
    'Graph only': { g: 1, a: 0.13, x: 0.13, e: 0.13 },
    'Adjacency A': { g: 0.3, a: 1, x: 0.13, e: 0.13 },
    'Node data X': { g: 0.3, a: 0.13, x: 1, e: 0.13 },
    'Edge data E': { g: 0.3, a: 0.13, x: 0.13, e: 1 }
  };
  var m = map[PANEL] || map['All panels'];
  gGraph.animate(220).attr('opacity', m.g);
  gA.animate(220).attr('opacity', m.a);
  gX.animate(220).attr('opacity', m.x);
  gE.animate(220).attr('opacity', m.e);
  gHi.attr('opacity', 1);
}

function drawHighlight() {
  gHi.clear();
  if (!SEL) return;
  if (SEL.type === 'node') {
    var n = SEL.id, nd = NODES[n];
    var ring = gHi.circle(2 * NR + 16).center(nd.x, nd.y).fill('none')
      .stroke({ color: C.nodeLite, width: 5, opacity: 0.65 });
    ring.animate(1100).attr({ 'stroke-opacity': 0.18 }).loop(true, true);
    gHi.rect(SQ + 10, 4 * SP + SQ + 10).radius(5).move(nd.sx - 5, nd.sy - 5)
      .fill('none').stroke({ color: C.nodeDark, width: 2.2, opacity: 0.9 });
    gHi.rect(AW + 10, CA + 8).radius(5).move(AGX - 5, AGY + (n - 1) * PA - 4)
      .fill({ color: C.slate, opacity: 0.2 }).stroke({ color: C.slateDk, width: 2, opacity: 0.75 });
    gHi.rect(CA + 8, AH + 10).radius(5).move(AGX + (n - 1) * PA - 4, AGY - 5)
      .fill({ color: C.slate, opacity: 0.2 }).stroke({ color: C.slateDk, width: 2, opacity: 0.75 });
    gHi.rect(CX + 10, XH + 10).radius(5).move(XGX + (n - 1) * PX - 5, XGY - 5)
      .fill('none').stroke({ color: C.brick, width: 3 });
  } else {
    var kk = SEL.k, e = EDGES[kk], a = NODES[e[0]], b = NODES[e[1]];
    var glow = gHi.line(a.x, a.y, b.x, b.y)
      .stroke({ color: C.edgeLite, width: 10, opacity: 0.45, linecap: 'round' });
    glow.animate(1100).attr({ 'stroke-opacity': 0.12 }).loop(true, true);
    gHi.line(a.x, a.y, b.x, b.y).stroke({ color: C.slateDk, width: 3.4, linecap: 'round' });
    [a, b].forEach(function (p) {
      gHi.circle(2 * NR + 10).center(p.x, p.y).fill('none')
        .stroke({ color: C.nodeLite, width: 2.4, opacity: 0.6 });
    });
    gHi.rect(SQ + 10, 3 * SP + SQ + 10).radius(5).move(ESTACK[kk][0] - 5, ESTACK[kk][1] - 5)
      .fill('none').stroke({ color: C.edgeDark, width: 2.2, opacity: 0.9 });
    [[e[0], e[1]], [e[1], e[0]]].forEach(function (p) {
      gHi.rect(CA + 8, CA + 8).radius(5).move(AGX + (p[1] - 1) * PA - 4, AGY + (p[0] - 1) * PA - 4)
        .fill('none').stroke({ color: C.slateDk, width: 3 });
    });
    gHi.rect(CE + 10, EH + 10).radius(5).move(EGX + kk * PE - 5, EGY - 5)
      .fill('none').stroke({ color: C.edgeDark, width: 3 });
  }
}

function updateInfo() {
  var el = document.getElementById('selInfo');
  if (!el) return;
  if (!SEL) { el.textContent = 'Nothing selected.'; return; }
  if (SEL.type === 'node') {
    var nb = neighbours(SEL.id);
    el.textContent = 'Node ' + SEL.id + ': degree ' + nb.length + ' (neighbours ' + nb.join(', ') +
      '). It is row ' + SEL.id + ' AND column ' + SEL.id + ' of A, and column ' + SEL.id + ' of X (5 features).';
  } else {
    var e = EDGES[SEL.k];
    el.textContent = 'Edge ' + e[0] + '–' + e[1] + ': filled at A[' + e[0] + ',' + e[1] + '] and A[' +
      e[1] + ',' + e[0] + '] (symmetric), and stored as column ' + (SEL.k + 1) + ' of E (4 features).';
  }
}

function syncGuided() {
  var g = document.getElementById('guidedHighlightInput');
  if (!g) return;
  var v = 'none';
  if (SEL && SEL.type === 'node' && (SEL.id === 3 || SEL.id === 5)) v = 'node ' + SEL.id;
  else if (SEL && SEL.type === 'edge') {
    var e = EDGES[SEL.k];
    if (e[0] === 3 && e[1] === 4) v = 'edge 3–4';
    else if (e[0] === 5 && e[1] === 6) v = 'edge 5–6';
    else v = 'custom';
  } else if (SEL) v = 'custom';
  g.value = v;
}

function render() { applyPanels(); drawHighlight(); updateInfo(); }

function selectNode(n, fromClick) {
  SEL = { type: 'node', id: n };
  syncGuided(); render();
  if (fromClick) {
    var nb = neighbours(n);
    showPopup('Node ' + n,
      'Node ' + n + ' appears three times in the encoding: as row ' + n + ' of A, as column ' + n +
      ' of A (both list its neighbours ' + nb.join(', ') + '), and as column ' + n +
      ' of the node-feature matrix X, which holds its D = 5 attribute values. ' +
      'The number of filled cells in its row of A, ' + nb.length + ', is its degree.');
  }
}
function selectEdge(k, fromClick) {
  SEL = { type: 'edge', k: k };
  syncGuided(); render();
  if (fromClick) {
    var e = EDGES[k];
    showPopup('Edge ' + e[0] + '–' + e[1],
      'Because the graph is undirected, this single edge is stored twice in A: at (' + e[0] + ',' + e[1] +
      ') and at (' + e[1] + ',' + e[0] + '). Its D_E = 4 attributes live in column ' + (k + 1) +
      ' of E, whose header names the endpoint pair. A alone tells you the edge exists; only E tells you what it carries.');
  }
}

function toggle_panelView(v) { PANEL = v; render(); }
function state_guidedHighlight(v) {
  if (v === 'custom') return;
  if (v === 'none') { SEL = null; }
  else if (v === 'node 3') { SEL = { type: 'node', id: 3 }; }
  else if (v === 'node 5') { SEL = { type: 'node', id: 5 }; }
  else if (v === 'edge 3–4') { SEL = { type: 'edge', k: edgeIndex(3, 4) }; }
  else if (v === 'edge 5–6') { SEL = { type: 'edge', k: edgeIndex(5, 6) }; }
  render();
}
function trigger_clear() {
  SEL = null;
  document.getElementById('guidedHighlightInput').value = 'none';
  hidePopup(); render();
}

