var STEP = 0;

function setStep(i) {
  STEP = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[STEP];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (STEP === 0 ? 'intro' : 'step ' + STEP + ' / 7');
  var pv = document.getElementById('panelViewInput');
  pv.value = s.state.panelView; toggle_panelView(s.state.panelView);
  var gh = document.getElementById('guidedHighlightInput');
  gh.value = s.state.guidedHighlight; state_guidedHighlight(s.state.guidedHighlight);
}
function nextStep() { setStep(STEP + 1); }
function prevStep() { setStep(STEP - 1); }

